$lines = [];
while ($line = fgets(STDIN)) {
    $lines[] = rtrim($line);
}

$current = array_shift($lines);
$words = $lines;
$lines = [];
echo $current, "\n";
do {
    $last = mb_str_split($current)[mb_strlen($current)-1];
    if ($last === 'ン') {
        echo "負けました\n";
        break;
    }
    foreach ($words as $i => $word) {
        if (str_starts_with($word, $last)) {
            echo $word, "\n";
            unset($words[$i]);
            $current = $word;
            continue 2;
        } 
    }
    exit("おかしいな\n");
} while(true);
